<template>
 <section class="career-page" v-loading="busy"><div class="career-breadcrumb"><el-button link @click="emit('back')">返回球队目录</el-button><span>/ 球队长期档案</span><el-button class="refresh" :loading="busy" @click="refresh">刷新档案</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="refresh">重新读取</el-button></el-alert>
 <template v-if="data"><header class="career-hero team-hero"><img v-if="logo" :src="logo" class="career-watermark" alt="" @error="logo=''"/><div class="career-identity"><small class="career-eyebrow">TEAM CAREER</small><h1>{{data.profile.name||'球队名待完善'}}</h1><div class="career-tags"><span>{{data.profile.city||'城市未登记'}}</span><span>平台长期档案</span></div><div class="career-bio"><span><small>当前正式球员</small>{{metric(data.currentRoster.count)}} 人</span><span><small>入驻平台</small>{{dateText(data.profile.registration?.registeredAt)}}</span><span><small>档案创建</small>{{dateText(data.profile.registration?.profileCreatedAt)}}</span></div></div><div class="team-head-summary"><label>正式赛事累计出场</label><strong>{{metric(data.official.totals.played)}}<small> 场</small></strong><p>历史贡献保留比赛当时的球队归属</p></div></header>
 <div class="team-year-control"><h2>球队数据</h2><el-select v-model="year" aria-label="统计年份" placeholder="全部年份"><el-option label="全部年份" value="all"/><el-option v-for="y in yearOptions" :key="y" :label="y+' 年'" :value="String(y)"/><el-option v-if="hasUndated" label="日期未知" value="unknown"/></el-select><span>{{year==='all'?'全平台生涯':year==='unknown'?'日期未知的记录':year+' 年度'}}</span></div>
 <div class="career-two"><section class="career-panel"><div class="career-panel-head"><h2>正式赛事</h2><span>{{officialCoverage==='complete'?'记录完整':'部分记录待核验'}}</span></div><div class="career-stats team-stats"><div v-for="field in teamMetrics" :key="field.key"><strong>{{metric(officialMetrics[field.key])}}</strong><small>{{field.label}}</small></div></div><p class="career-muted">正式归档赛果；不计测试和友谊赛。</p></section><section class="career-panel"><div class="career-panel-head"><h2>日常约球</h2><span>{{friendlyView?.coverage==='complete'?'记录已核验':'含未核验记录'}}</span></div><div class="career-stats team-stats"><div v-for="field in teamMetrics" :key="field.key"><strong>{{metric(friendlyView?.metrics?.[field.key])}}</strong><small>{{field.label}}</small></div></div><p class="career-muted">球队自报口径，独立于官方赛事排名。</p></section></div>
 <section class="career-panel"><div class="career-panel-head"><h2>约球活动概况</h2><span>报名、成赛与取消分开</span></div><div class="career-stats"><div v-for="field in activityFields" :key="field.key"><strong>{{metric(friendlyView?.observed?.[field.key])}}</strong><small>{{field.label}}</small></div></div><div class="career-panel-foot"><span>邀请发起 {{metric(invitationView?.recorded)}} 次 · 已取消 {{metric(invitationView?.cancelled)}} 次</span><span>邀请按发起年份统计，比赛按发生年份统计</span></div><p v-if="friendlyView?.observed?.participantSourceUnverified||friendlyView?.observed?.opponentSourceUnverified" class="career-warning">部分自报比赛缺少参赛球员或对手的稳定身份，不作为已核定战绩。</p></section>
 <section class="career-panel"><div class="career-panel-head"><h2>年份数据</h2><span>年度与生涯可对账</span></div><el-table :data="annualRows" empty-text="暂无可归属年份的比赛记录"><el-table-column label="年份" width="100"><template #default="{row}">{{row.year==null?'日期未知':row.year}}</template></el-table-column><el-table-column label="正式场次"><template #default="{row}">{{metric(row.official?.totals.played)}}</template></el-table-column><el-table-column label="正式胜 / 平 / 负" min-width="170"><template #default="{row}">{{metric(row.official?.totals.wins)}} / {{metric(row.official?.totals.draws)}} / {{metric(row.official?.totals.losses)}}</template></el-table-column><el-table-column label="正式进 / 失球"><template #default="{row}">{{metric(row.official?.totals.goalsFor)}} / {{metric(row.official?.totals.goalsAgainst)}}</template></el-table-column><el-table-column label="约球已结束记录" min-width="150"><template #default="{row}">{{metric(row.friendly?.observed.finished)}}</template></el-table-column><el-table-column label="约球核定场次"><template #default="{row}">{{metric(row.friendly?.metrics.played)}}</template></el-table-column></el-table></section>
 <section class="career-panel"><div class="career-panel-head"><h2>历届赛事</h2><span>不按当前球员名单回算</span></div><el-table :data="data.statistics.teams" empty-text="暂无正式参赛统计"><el-table-column label="赛事" min-width="190"><template #default="{row}">{{tournamentName(row.tournamentId)}}</template></el-table-column><el-table-column label="组别" min-width="120"><template #default="{row}">{{divisionName(row.divisionId)}}</template></el-table-column><el-table-column v-for="field in teamMetrics" :key="field.key" :label="field.label" width="85"><template #default="{row}">{{metric(row[field.key])}}</template></el-table-column></el-table></section>
 <section class="career-panel"><div class="career-panel-head"><h2>球员历史贡献</h2><span>允许转队后继续追溯</span></div><el-table :data="contributions" empty-text="暂无可核定球员记录"><el-table-column label="球员" min-width="140"><template #default="{row}"><el-button link type="primary" @click="emit('player',row.playerId)">{{row.playerName||'姓名待核验'}}</el-button></template></el-table-column><el-table-column label="赛事" min-width="180"><template #default="{row}">{{tournamentName(row.tournamentId)}}</template></el-table-column><el-table-column label="出场"><template #default="{row}">{{metric(row.metrics.appearances)}}</template></el-table-column><el-table-column label="进球"><template #default="{row}">{{metric(row.metrics.goals)}}</template></el-table-column><el-table-column label="助攻"><template #default="{row}">{{metric(row.metrics.assists)}}</template></el-table-column><el-table-column label="分钟"><template #default="{row}">{{metric(row.metrics.minutesPlayed)}}</template></el-table-column></el-table><el-pagination v-if="data.statistics.players.length>20" v-model:current-page="contributionPage" :page-size="20" :total="data.statistics.players.length" layout="prev,pager,next,total"/></section>
 <details class="career-version"><summary>来源、完整度与版本</summary><p>数据 {{data.dataVersion}} · 指标 {{data.statistics.metricVersion}}</p><p>正式记录问题 {{data.statistics.issues?.length??0}} 项 · 测试约球排除 {{data.friendly.excluded.test}} 条</p></details>
 </template></section>
</template>
<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {getFileUrl} from '../../utils/cloud'
import {dataHub,dateText,metric,safeImage,teamMetrics} from './dataHubApi'
import './career.css'
const props=defineProps({teamId:{type:String,required:true}}),emit=defineEmits(['back','player']),data=ref(null),busy=ref(false),error=ref(''),logo=ref(''),year=ref('all'),contributionPage=ref(1)
let seq=0
const activityFields=[{key:'records',label:'记录总数'},{key:'scheduled',label:'报名中 / 待赛'},{key:'finished',label:'已结束记录'},{key:'cancelled',label:'已取消'},{key:'scoreUnknown',label:'比分待核验'}]
const yearOptions=computed(()=>[...new Set([...(data.value?.official.annual?.years||[]).map(x=>x.year),...(data.value?.friendly.years||[]).map(x=>x.year),...(data.value?.friendly.invitations.years||[]).map(x=>x.year)])].sort((a,b)=>b-a)),hasUndated=computed(()=>Boolean(data.value?.official.annual?.undated||data.value?.friendly.undated||data.value?.friendly.invitations.undated))
const officialView=computed(()=>year.value==='all'?null:year.value==='unknown'?data.value?.official.annual?.undated:data.value?.official.annual?.years.find(x=>String(x.year)===year.value)),officialMetrics=computed(()=>year.value==='all'?data.value?.official.totals||{}:officialView.value?.totals||{}),officialCoverage=computed(()=>year.value==='all'?data.value?.statistics.coverage.status:officialView.value?.coverage.status)
const friendlyView=computed(()=>year.value==='all'?data.value?.friendly.lifetime:year.value==='unknown'?data.value?.friendly.undated:data.value?.friendly.years.find(x=>String(x.year)===year.value)),invitationView=computed(()=>year.value==='all'?data.value?.friendly.invitations:year.value==='unknown'?data.value?.friendly.invitations.undated:data.value?.friendly.invitations.years.find(x=>String(x.year)===year.value))
const annualRows=computed(()=>[...yearOptions.value.map(y=>({year:y,official:data.value?.official.annual?.years.find(x=>x.year===y),friendly:data.value?.friendly.years.find(x=>x.year===y)})),...(hasUndated.value?[{year:null,official:data.value?.official.annual?.undated,friendly:data.value?.friendly.undated}]:[])])
const contributions=computed(()=>data.value?.statistics.players.slice((contributionPage.value-1)*20,contributionPage.value*20)||[])
const tournamentName=id=>data.value?.scopes?.tournaments.find(x=>x.id===id)?.name||'赛事名称待核验',divisionName=id=>data.value?.scopes?.divisions.find(x=>x.id===id)?.name||(id==='default'?'默认组别':'组别待核验')
async function refresh(){const s=++seq;busy.value=true;error.value='';data.value=null;logo.value='';year.value='all';contributionPage.value=1;try{const r=await dataHub('hubTeamProfile',{teamId:props.teamId});if(s!==seq)return;data.value=r;getFileUrl(r.profile.logo||'').then(img=>{if(s===seq)logo.value=safeImage(img)}).catch(()=>{})}catch(e){if(s===seq)error.value=e.message}finally{if(s===seq)busy.value=false}}
watch(()=>props.teamId,refresh,{immediate:true});onBeforeUnmount(()=>{seq++});defineExpose({refresh,loading:busy})
</script>
